{
  "correction_rules": [
    "When sentiment is positive (≥ 0.33), model tends to underpredict; increase forecast by 2–5% to align with upward momentum.",
    "When sentiment is negative (≤ -0.25), model tends to overpredict; reduce forecast by 3–7% to avoid overreaction.",
    "After a sharp price spike (≥ 10% from prior peak), model often overshoots; apply a 10–15% downward correction to prevent overcorrection.",
    "Model consistently underestimates mean reversion in 3–5 day horizons; add 1–3% to forecast for short-term mean reversion bias.",
    "In high volatility periods (sentiment > 0.5), model lags behind true price; apply a 1–2 day lead correction to anticipate momentum.",
    "When sentiment is flat (0.00), model exhibits high noise; use 30-day moving average to smooth and stabilize forecast."
  ]
}
